const binance = $input.all()[0].json;
const coinbase = $input.all()[1].json;
const min_spread = $input.all()[0].json.min_spread_pct || 0.5;
const trade_amount = $input.all()[0].json.trade_amount_usd || 10000;
const fee_rate = $input.all()[0].json.fee_rate_pct || 0.1;

const pairs = [BTC-USDT, ETH-USDT, SOL-USDT];
const opportunities = [];

// Simulate multi-exchange prices
const exchange_prices = {
  BTC-USDT: {
    binance: 67500 + (Math.random() - 0.5) * 100,
    coinbase: 67500 + (Math.random() - 0.5) * 100,
    kraken: 67500 + (Math.random() - 0.5) * 100,
    kucoin: 67500 + (Math.random() - 0.5) * 100,
    okx: 67500 + (Math.random() - 0.5) * 100
  },
  ETH-USDT: {
    binance: 3450 + (Math.random() - 0.5) * 20,
    coinbase: 3450 + (Math.random() - 0.5) * 20,
    kraken: 3450 + (Math.random() - 0.5) * 20,
    kucoin: 3450 + (Math.random() - 0.5) * 20,
    okx: 3450 + (Math.random() - 0.5) * 20
  }
};

for (const pair of pairs) {
  if (!exchange_prices[pair]) continue;

  const prices = exchange_prices[pair];
  const exchanges = Object.keys(prices);

  // Find min and max prices
  let min_price = Infinity, max_price = 0;
  let buy_exchange = , sell_exchange = ;

  for (const exchange of exchanges) {
    if (prices[exchange] < min_price) {
      min_price = prices[exchange];
      buy_exchange = exchange;
    }
    if (prices[exchange] > max_price) {
      max_price = prices[exchange];
      sell_exchange = exchange;
    }
  }

  // Calculate spread
  const spread_pct = ((max_price - min_price) / min_price) * 100;

  if (spread_pct >= min_spread) {
    const gross_profit = (max_price - min_price) * (trade_amount / min_price);
    const fees = trade_amount * (fee_rate / 100) * 2; // Buy + sell fees
    const net_profit = gross_profit - fees;

    // Risk score (lower spread = higher risk of execution failure)
    const risk_score = Math.max(0, 100 - (spread_pct * 10));

    opportunities.push({
      pair: pair,
      buy_exchange: buy_exchange,
      sell_exchange: sell_exchange,
      buy_price: Math.round(min_price * 100) / 100,
      sell_price: Math.round(max_price * 100) / 100,
      spread_pct: Math.round(spread_pct * 100) / 100,
      estimated_profit_usd: Math.round(net_profit * 100) / 100,
      risk_score: Math.round(risk_score * 100) / 100,
      timestamp: new Date().toISOString()
    });
  }
}

return opportunities.map(opp => ({json: opp}));

const opportunities = $input.all();

// Write to CASD cache
for (const item of opportunities) {
  const cache_key = `arbitrage:${item.json.pair}`;
  await casd.set(cache_key, item.json, {ttl: 10}); // 10 second TTL (fast-moving data)
}

return opportunities;
